import React, { useState } from 'react';
import { AlertTriangle, ChevronDown, ChevronUp, ShieldAlert } from 'lucide-react';

interface DisclaimerProps {
  customText?: string;
  defaultExpanded?: boolean;
}

export const Disclaimer: React.FC<DisclaimerProps> = ({
  customText,
  defaultExpanded = true,
}) => {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded);

  const fallbackText =
    'IMPORTANT: This system is generated by an AI application for informational and educational purposes only. ' +
    'It is NOT a medical diagnosis, prescription, or clinical treatment plan, and does NOT replace professional ' +
    'medical evaluation, diagnosis, or care. Always consult a qualified, licensed healthcare professional for any ' +
    'medical decisions, emergencies, or symptom management. Verify all findings directly with your treating physician.';

  const textToDisplay = customText || fallbackText;

  return (
    <aside
      aria-label="Medical Disclaimer"
      className="bg-amber-50/90 border-b border-amber-200 text-amber-900 transition-all duration-200"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-2.5">
        <div className="flex items-start justify-between gap-3">
          {/* Warning Icon & Heading */}
          <div className="flex items-start gap-2.5 flex-1">
            <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" aria-hidden="true" />
            <div className="text-xs sm:text-sm">
              <span className="font-semibold text-amber-950">
                Medical Disclaimer:{' '}
              </span>
              {isExpanded ? (
                <span className="text-amber-800 leading-relaxed block sm:inline mt-0.5 sm:mt-0">
                  {textToDisplay}
                </span>
              ) : (
                <span className="text-amber-800">
                  AI-assisted clinical decision support tool. Informational only — not medical advice.
                </span>
              )}
            </div>
          </div>

          {/* Expand/Collapse Toggle Button */}
          <button
            type="button"
            onClick={() => setIsExpanded(!isExpanded)}
            className="shrink-0 p-1 text-amber-700 hover:text-amber-950 hover:bg-amber-100/80 rounded transition-colors focus:outline-none focus:ring-2 focus:ring-amber-500"
            title={isExpanded ? 'Collapse disclaimer' : 'Expand full disclaimer'}
            aria-expanded={isExpanded}
          >
            {isExpanded ? (
              <ChevronUp className="w-4 h-4" />
            ) : (
              <div className="flex items-center space-x-1 text-xs font-medium">
                <span>Details</span>
                <ChevronDown className="w-4 h-4" />
              </div>
            )}
          </button>
        </div>

        {isExpanded && (
          <div className="mt-2 pt-2 border-t border-amber-200/60 flex items-center gap-1.5 text-[11px] text-amber-700">
            <ShieldAlert className="w-3.5 h-3.5" />
            <span>AI extraction may misinterpret handwritten notes or low-resolution scans. Cross-reference source references provided with original medical records.</span>
          </div>
        )}
      </div>
    </aside>
  );
};
